PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member ?name ?membership ?constituency ?label ?term ?termLabel ?range ?start ?end WHERE {
  VALUES ?member { <https://data.oireachtas.ie/ie/oireachtas/member/id/Mary-Lou-McDonald.D.2011-03-09> }
  GRAPH ?memberGraph {
    ?member a agents:Member ; foaf:name ?name ; members:hasMembersMembership ?membership .
    ?membership a members:DailMembership ; members:inHouseTerm ?term ; members:isRepresentativeFrom ?constituency .
    OPTIONAL { ?membership members:hasMembershipDateRange ?range .
      OPTIONAL { ?range members:StartDate ?start . } OPTIONAL { ?range members:EndDate ?end . } }
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/constituencies> { ?constituency a members:DailConstituency ;
    members:constituencyInHouseTerm ?term . ?constituency skos:prefLabel ?label . }
  GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a agents:DailTerm . ?term skos:prefLabel ?termLabel . }
} ORDER BY ?member ?membership ?constituency ?term ?name ?label ?termLabel ?range ?start ?end LIMIT 100

PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member ?name ?membership ?term ?termLabel ?termStart ?termEnd ?membershipStart ?membershipEnd ?representation ?representationLabel WHERE {
  GRAPH ?memberGraph {
    VALUES ?member { <https://data.oireachtas.ie/ie/oireachtas/member/id/Mary-Lou-McDonald.D.2011-03-09> }
    ?member a agents:Member ; foaf:name ?name ; members:hasMembersMembership ?membership .
    ?membership a members:DailMembership ; members:inHouseTerm ?term .
    OPTIONAL { ?membership members:isRepresentativeFrom ?representation . }
    OPTIONAL { ?membership members:hasMembershipDateRange ?membershipRange .
      ?membershipRange a members:DateRange .
      OPTIONAL { ?membershipRange members:StartDate ?membershipStart . }
      OPTIONAL { ?membershipRange members:EndDate ?membershipEnd . }
    }
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/houses> {
    ?term a agents:DailTerm ; skos:prefLabel ?termLabel ; agents:termOf ?house ; dct:temporal ?period .
    ?period a dct:PeriodOfTime .
    ?period dcat:startDate ?termStart . OPTIONAL { ?period dcat:endDate ?termEnd . }
  }
} ORDER BY ?membershipStart ?term
LIMIT 100

PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?billGraph ?bill ?participation ?primaryEvidence ?participationRole ?englishTitle ?billNumber ?billYear ?publishedActivity ?publishedDate WHERE {
  GRAPH ?billGraph {
    ?bill a eli-dl:DraftLegislationWork ; eli:work_type agents:Bill .
    ?delivery a agents:BillDelivery ; eli-dl:created_a_realization_of ?bill ; eli-dl:forms_part_of ?process .
    ?process a eli-dl:LegislativeProcess ; eli-dl:had_participation ?participation .
    ?participation a eli-dl:Participation ; eli-dl:had_participant_person <https://data.oireachtas.ie/ie/oireachtas/member/id/Malcolm-Byrne.D.2019-11-29> .
    OPTIONAL { ?participation agents:isPrimarySponsor ?primaryEvidence . }
    OPTIONAL { ?participation rdfs:label ?participationRole . }
    OPTIONAL { ?bill dct:title ?englishTitle . FILTER(LANG(?englishTitle) = "en") }
    OPTIONAL { ?process eli-dl:process_number ?billNumber . }
    OPTIONAL { ?bill agents:legislativeYear ?billYear . }

    OPTIONAL {
      ?publishedActivity a eli-dl:LegislativeActivity ; eli-dl:forms_part_of ?process ; eli-dl:had_activity_type agents:Published .
      OPTIONAL { ?publishedActivity eli-dl:activity_date ?publishedDate . }
    }
  }
  FILTER(REGEX(STR(?billGraph), "^https://data\\.oireachtas\\.ie/graph/bill/[0-9]{4}/[^/]+$"))
} ORDER BY ?billYear ?billNumber ?bill ?participation ?primaryEvidence ?participationRole ?englishTitle ?billGraph ?publishedDate ?publishedActivity LIMIT 100
